function reviewOrder(){S.order.f.name=$('#o_name').value;S.order.f.phone=$('#o_phone').value;const c=chef(S.order.chef),error=window.ChefValidation.validateOrder(S.order,undefined,c);if(error){$('#order-error').textContent=error;const id=error.includes('nome')?'o_name':error.includes('telefone')?'o_phone':error.includes('e-mail')?'o_email':error.includes('data')?'o_date':error.includes('marmitas por entrega')?'o_mqty':null;id?$('#'+id).focus():$('#order-error').scrollIntoView({block:'center'});return}persistDraft();const text=C.buildOrderText(c,S.order);sheet('<h2 id="dialog-title">Confira seu pedido</h2><p class="form-help">'+(c.isDemo?'Este é um perfil de exemplo: o WhatsApp abre no número de teste do projeto, não com um chef real. Abrir o aplicativo não confirma o envio.':'Confira os detalhes antes de abrir o WhatsApp. Abrir o aplicativo não confirma o envio do pedido.')+'</p><p class="form-help">O Seu Chef em Casa é uma vitrine: valores, serviço e pagamento são combinados direto com o chef. Veja os <a href="#/termos">termos</a>.</p><pre class="order-preview">'+esc(text)+'</pre><div class="acts"><button class="b b2" data-a="copyorder">Copiar pedido</button>'+(C.phone(c.whatsapp)?'<button class="b b1" data-a="sendorder">Abrir WhatsApp '+ic('wa',18)+'</button>':'')+'</div>')}
function posPedido(c){sheet('<h2 id="dialog-title">Envie o pedido pelo WhatsApp</h2><p class="form-help">'+(c.isDemo?'Este é um perfil de exemplo: a conversa abre no número de teste do projeto.':'Seu pedido está pronto na conversa com '+esc(c.name)+', mas só chega ao chef depois que você enviar.')+'</p><ol class="passos"><li><b>Toque em Enviar no WhatsApp.</b> O texto já vem preenchido, e você pode ajustar o que quiser.</li><li><b>Aguarde a resposta do chef.</b> Ele confirma a data e o valor por lá.</li><li><b>Combine os detalhes direto com ele.</b> Cardápio, ingredientes e pagamento são acertados entre vocês.</li></ol><p class="form-help">O WhatsApp não abriu ou você fechou sem enviar? Use os botões abaixo.</p><div class="acts"><button class="b b1" data-a="reabrirwa">'+ic('wa',18)+' Abrir WhatsApp de novo</button><button class="b b2" data-a="copyorder">Copiar pedido</button><a class="b b2" href="#/buscar">Ver outros chefs</a></div>')}
function openWhatsApp(c,text){const n=C.phone(c.whatsapp);if(!n){toast(c.isDemo?'Este perfil de exemplo não tem número de teste.':'O chef ainda não informou um WhatsApp válido.');return false}window.open('https://wa.me/'+n+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');toast('Envie a mensagem na conversa do WhatsApp.');return true}
