  const st=S.eq,l=st.list||[],vis=l.filter(x=>!x.oculto&&!x.pausado&&!x.falta.length).length,p7=l.reduce((a,x)=>a+(x.pedidos7||0),0),pt=l.reduce((a,x)=>a+(x.pedidos||0),0);
  const filtro=S.eqf||'todos',F={todos:()=>true,visiveis:x=>!x.oculto&&!x.pausado&&!x.falta.length,incompletos:x=>x.falta.length>0,escondidos:x=>x.oculto||x.pausado};
