  const lista=l.filter(F[filtro]).filter(x=>C.norm([x.nome,x.email,x.cidades].join(' ')).includes(C.norm(S.eqq||'')));if(!lista.length)return h+'<p class="empty">Nenhum chef aqui.</p></div>';
