function socialFoto(c,p){if(!socialOn(c))return '';const s=(S.social||{})[c.id],f=(s&&s.fotos[String(p.id)])||{curtidas:0,curti:false,comentarios:0};return '<div class="social-bar"><button type="button" class="social-btn'+(f.curti?' on':'')+'" data-a="curtir" data-chef="'+esc(c.id)+'" data-foto="'+esc(p.id)+'" aria-pressed="'+f.curti+'" aria-label="Curtir">'+ic('heart',24,f.curti?'currentColor':'')+'<b>'+f.curtidas+'</b></button><button type="button" class="social-btn" data-a="vercoments" data-chef="'+esc(c.id)+'" data-foto="'+esc(p.id)+'">'+ic('chat',23)+'<b>'+f.comentarios+'</b> comentários</button></div><div id="coments" class="coments"></div>'}
