async function esqueci(f){const err=$('#esqueci-error'),em=$('#esq_email').value.trim(),bt=f.querySelector('button');err.textContent='';if(!C.validEmail(em)){err.textContent='Confira o e-mail informado.';return}bt.disabled=true;try{await CL.esqueci(em);f.innerHTML='<div class="note" role="status"><b>Pronto.</b> Se existir uma conta com '+esc(em)+', enviamos um link para criar a senha nova. Confira também a caixa de spam. O link vale por 1 hora.</div>'}catch(e){err.textContent=e.message||'Não foi possível enviar.';bt.disabled=false}}
