function escolhaTipo(){return '<section class="card escolha"><h1>Como você quer usar o Seu Chef em Casa?</h1><div class="escolha-grid"><button type="button" class="escolha-op" data-a="tipo" data-v="cliente"><b>Quero contratar um chef</b><span>Peça orçamentos e acompanhe os chefs que você gosta.</span></button><button type="button" class="escolha-op" data-a="tipo" data-v="chef"><b>Sou chef</b><span>Monte seu perfil e receba pedidos de orçamento.</span></button></div><p class="form-help c">Já tem conta? Escolha uma opção e toque em Entrar.</p></section>'}
