function cropAvatar(image){
  uploadImage={type:'avatar'};
  sheet('<h2 id="dialog-title">Recorte sua foto de perfil</h2><p class="form-help" id="crop-help">Arraste a imagem ou use as setas para reposicionar. O círculo mostra como a foto vai aparecer.</p><div class="avatar-crop"><canvas id="avatar-crop" width="450" height="450" tabindex="0" aria-label="Posição da foto" aria-describedby="crop-help"></canvas></div><div class="f"><label for="avatar-zoom">Aproximar</label><input id="avatar-zoom" type="range" min="1" max="3" step="0.05" value="1"></div><button class="b b1 full" data-a="publishphoto">Salvar foto de perfil</button>');
  const canvas=$('#avatar-crop'),zoom=$('#avatar-zoom'),ctx=canvas.getContext('2d'),size=canvas.width;
  const base=Math.min(image.naturalWidth,image.naturalHeight);
  let x=image.naturalWidth/2,y=base/2,drag=null;
  const side=()=>base/Number(zoom.value);
  function draw(){
    const width=side(),half=width/2;
    x=Math.min(image.naturalWidth-half,Math.max(half,x));
    y=Math.min(image.naturalHeight-half,Math.max(half,y));
    ctx.fillStyle='#fff';
    ctx.fillRect(0,0,size,size);
    ctx.drawImage(image,x-half,y-half,width,width,0,0,size,size);
  }
  canvas.addEventListener('pointerdown',e=>{
    if(!e.isPrimary||e.button!==0)return;
    canvas.setPointerCapture(e.pointerId);
    drag={x:e.clientX,y:e.clientY};
  });
  canvas.addEventListener('pointermove',e=>{
    if(!drag||!canvas.hasPointerCapture(e.pointerId))return;
    const scale=side()/canvas.getBoundingClientRect().width;
    x-=(e.clientX-drag.x)*scale;
    y-=(e.clientY-drag.y)*scale;
    drag={x:e.clientX,y:e.clientY};
    draw();
  });
  canvas.addEventListener('lostpointercapture',()=>{drag=null});
  canvas.addEventListener('keydown',e=>{
    const offset={ArrowLeft:[1,0],ArrowRight:[-1,0],ArrowUp:[0,1],ArrowDown:[0,-1]}[e.key];
    if(!offset)return;
    e.preventDefault();
    x+=offset[0]*side()/20;
    y+=offset[1]*side()/20;
    draw();
  });
  zoom.addEventListener('input',draw);
  draw();
}
async function upload(file,type){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024){toast('Escolha uma imagem JPG, PNG ou WebP de até 10 MB.');return}toast('Preparando sua foto…');try{const url=URL.createObjectURL(file),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url});if(type==='avatar'){cropAvatar(image);return}const ratio=Math.min(1,1200/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*ratio);canvas.height=Math.round(image.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);uploadImage={type,url:canvas.toDataURL('image/jpeg',.82)};sheet('<h2 id="dialog-title">Adicionar ao portfólio</h2><img class="upload-preview" src="'+uploadImage.url+'" alt="Prévia da foto escolhida">'+(type==='feed'?'<div class="f"><label for="photo-caption">Legenda da foto</label><textarea id="photo-caption" maxlength="600" placeholder="Ex.: jantar para seis pessoas, com massa fresca."></textarea></div>':'')+'<button class="b b1 full" data-a="publishphoto">Salvar no portfólio</button>')}finally{URL.revokeObjectURL(url)}}catch(e){toast('Não foi possível abrir essa imagem. Escolha outro arquivo.')}}
