  seguir:async el=>{if(!ME)return exigirConta('Crie sua conta grátis para seguir chefs.');const id=el.dataset.id,s=(S.social||{})[id],on=!(s&&s.sigo);el.disabled=true;try{const r=await CL.seguir(id,on);if(s){s.sigo=r.sigo;s.seguidores=r.seguidores}render(false)}catch(e){toast(e.message||'Não foi possível seguir.');el.disabled=false}},curtir:async el=>{if(!ME)return exigirConta('Crie sua conta grátis para curtir.');const id=el.dataset.chef,foto=el.dataset.foto,s=(S.social||{})[id],f=s&&(s.fotos[foto]||(s.fotos[foto]={curtidas:0,curti:false,comentarios:0})),on=!(f&&f.curti);el.disabled=true;try{const r=await CL.curtir(id,foto,on);if(f){f.curti=r.curti;f.curtidas=r.curtidas}if(photoState)photo(photoState.id,photoState.index)}catch(e){toast(e.message||'Não foi possível curtir.');el.disabled=false}},vercoments:el=>abrirComentarios(el.dataset.chef,el.dataset.foto),sino:()=>abrirAvisos(),denunciar:async el=>{el.disabled=true;try{await CL.denunciar(el.dataset.id);el.textContent='denunciado';toast('Obrigado. A equipe vai analisar este comentário.')}catch(e){el.disabled=false;toast(e.message||'Não foi possível denunciar.')}},loginsocial:()=>exigirConta('Crie sua conta grátis para comentar.'),apagarcoment:async el=>{try{await CL.apagarComentario(el.dataset.id);const s=(S.social||{})[el.dataset.chef],x=s&&s.fotos[el.dataset.foto];if(x&&x.comentarios)x.comentarios--;abrirComentarios(el.dataset.chef,el.dataset.foto)}catch(e){toast(e.message||'Não foi possível apagar.')}},tipo:el=>{S.tipo=el.dataset.v;if(el.dataset.ir){S.auth='up';location.hash='#/entrar'}render(false)},authtab:el=>{S.auth=el.dataset.v;render(false)},
