  forgot:()=>{const cfg=siteConfig(),wa=C.phone(cfg.supportWhatsapp);sheet('<h2 id="dialog-title">Recuperar senha</h2>'+(cloudOn()?'<form id="esqueci-form" novalidate><p class="form-help">Informe o e-mail da sua conta. Enviamos um link para você criar uma senha nova.</p>'+field('esq_email','E-mail','','email','autocomplete="username"')+'<p class="err" id="esqueci-error" role="alert"></p><button class="b b1 full" type="submit">Enviar link</button></form><p class="form-help" style="margin-top:14px">Não recebeu? Fale com a equipe do Seu Chef em Casa'+(wa?' pelo WhatsApp':cfg.contactEmail?' por e-mail':cfg.instagram?' pelo Instagram':'')+'.</p>'+(wa?'<p style="margin-top:14px"><a class="b b1 full" href="https://wa.me/'+wa+'?text='+encodeURIComponent('Olá! Preciso de ajuda para recuperar minha senha no Seu Chef em Casa.')+'" target="_blank" rel="noopener noreferrer">Falar com a equipe no WhatsApp</a></p>':(cfg.contactEmail?'<p style="margin-top:14px"><a class="b b1 full" href="mailto:'+esc(cfg.contactEmail)+'?subject='+encodeURIComponent('Recuperação de senha · Seu Chef em Casa')+'">Enviar e-mail para a equipe</a></p>':(cfg.instagram?'<p style="margin-top:14px"><a class="b b1 full" href="'+esc(cfg.instagram)+'" target="_blank" rel="noopener noreferrer">Falar com a equipe no Instagram</a></p>':''))):'<p class="form-help">Se você possui uma conta local, use o mesmo navegador e a senha criada nele. A recuperação por e-mail precisa ser implementada junto com a autenticação do servidor.</p>')+'<button class="b b2 full" data-a="close">Entendi</button>')},
