  instalarapp:async()=>{const t=await window.ChefApp.instalar();if(t)toast(t);render(false)},shareperfil:async()=>{const c=chef(ME);if(!c)return;if(C.faltaPerfil(c).length||c.pausado||c.oculto){toast('Seu perfil ainda não está visível para os clientes. Complete o que falta antes de compartilhar.');return}const url=location.origin+'/chef/'+C.slugChef(c.name,c.id),texto='Veja meu cardápio, fotos e como pedir um orçamento:';try{if(navigator.share){await navigator.share({title:c.name+' · Seu Chef em Casa',text:texto,url});return}await navigator.clipboard.writeText(texto+' '+url);toast('Link copiado. Cole no WhatsApp, Instagram ou onde quiser.')}catch(e){if(e&&e.name==='AbortError')return;toast('Seu link: '+url)}},
  google:async el=>{const err=$('#auth-error'),modo=el.dataset.v,fail=(t,f)=>{err.textContent=t;el.disabled=false;const c=f&&$(f);if(c){c.scrollIntoView({block:'center',behavior:'smooth'});c.focus()}else err.scrollIntoView({block:'center'})};err.textContent='';let dados={};if(modo==='cadastro'){if(cidadeCadastroPendente())return;dados={nome:$('#a_name').value.trim(),whatsapp:$('#a_whatsapp').value.trim(),cidades:($('#a_cities')||{value:''}).value.trim(),convite:($('#a_convite')||{value:''}).value.trim()};if((el.dataset.tipo||S.tipo)!=='cliente'&&CL.temConvite&&!dados.convite)return fail('Informe o código de convite.','#a_convite');}dados.tipo=(el.dataset.tipo||S.tipo)==='cliente'?'cliente':'chef';el.disabled=true;try{if(location.hash==='#/entrar/admin')sessionStorage.setItem('sc_admin_return','1');location.href=await CL.google(modo,dados)}catch(e){fail(e.message||'Não foi possível abrir o Google.')}},
