  pedwa:el=>{const t=S.pedTexts[el.dataset.id]||'',n=C.phone(pedidoCampo(t,'Telefone')),c=chef(ME);if(!n){toast('Este pedido não tem um telefone válido.');return}window.open('https://wa.me/'+n+'?text='+encodeURIComponent('Olá, '+(pedidoCampo(t,'Cliente')||'tudo bem')+'! Aqui é '+(c?c.name:'o chef')+', do Seu Chef em Casa. Recebi seu pedido de orçamento.'),'_blank','noopener,noreferrer');toast('Envie a mensagem na conversa do WhatsApp.')},
