  excluirconta:()=>sheet('<h2 id="dialog-title">Excluir sua conta?</h2><p class="form-help">Seu perfil, fotos, cardápio e pedidos recebidos serão apagados para sempre. Não dá para desfazer. Se quiser só dar um tempo, use Pausar perfil.</p><div class="f"><label for="del-confirm">Para confirmar, digite EXCLUIR</label><input id="del-confirm" autocomplete="off"></div><p class="err" id="del-error" role="alert"></p><div class="acts"><button class="b b2" data-a="close">Cancelar</button><button class="b b1" data-a="confirmexcluir">Excluir minha conta</button></div>'),
  confirmexcluir:async el=>{const err=$('#del-error');if(cloudSaving){err.textContent='Aguarde o salvamento em andamento antes de excluir.';return}if($('#del-confirm').value.trim().toUpperCase()!=='EXCLUIR'){err.textContent='Digite EXCLUIR para confirmar.';return}if(S.busy)return;S.busy=true;el.disabled=true;err.textContent='';try{const c=chef(ME),id=ME;if(c?.cloud&&cloudOn()){clearTimeout(cloudTimer);await CL.excluir();DATA.chefs=DATA.chefs.filter(c=>c.id!==id);}else if(!realMode){if(!commit(d=>{d.chefs=d.chefs.filter(c=>c.id!==id);d.orders=(d.orders||[]).filter(o=>o.chefId!==id);d.messages=(d.messages||[]).filter(m=>m.chefId!==id&&m.clientId!=='account:'+id)}))throw new Error('Não foi possível excluir a conta local.');}else throw new Error('Conecte-se ao servidor antes de excluir.');clearTimeout(cloudTimer);session(null);window.ChefManagement.reset();S.eq=null;S.eqLink=null;S.ped=null;S.profileDraft=null;closeSheet();location.hash='#/';toast('Sua conta foi excluída.')}catch(e){err.textContent=e.status===404||e.status===405?'A exclusão automática ainda não está disponível. Nada foi apagado.':e.status===401?'Sua sessão expirou. Entre de novo para excluir a conta.':(e.message||'Não foi possível excluir a conta. Nada foi apagado.');el.disabled=false}finally{S.busy=false}},
